import type { Metadata } from "next";
import { Geist, Geist_Mono, Outfit } from "next/font/google";
import "./globals.css";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import UXWrapper from "@/components/UXWrapper";

const outfit = Outfit({
  variable: "--font-outfit",
  subsets: ["latin"],
  weight: ["300", "400", "500", "700", "900"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "IMC SERVICIOS SPA | Especialistas en Construcción y Mantenimiento",
  description: "Tranquilidad para su empresa y su hogar. Reparaciones, remodelaciones y servicios técnicos con maestros expertos en todo Chile. Calidad certificada.",
  keywords: ["construcción", "mantenimiento industrial", "remodelación de casas", "servicios eléctricos", "IMC SERVICIOS SPA"],
  icons: {
    icon: "/img/logo/logo.jpg",
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="es" className="scroll-smooth">
      <body className={`${outfit.variable} ${geistMono.variable} antialiased bg-black mesh-gradient noise min-h-screen`}>
        <UXWrapper>
          <Navbar />
          {children}
          <Footer />
        </UXWrapper>
      </body>
    </html>
  );
}

"use client";

import { useState } from "react";
import Hero from "@/components/Hero";
import MainServices from "@/components/MainServices";
import About from "@/components/About";
import ExperienceHighlights from "@/components/ExperienceHighlights";
import Gallery from "@/components/Gallery";
import { ShieldCheck, Clock, Award, CheckCircle2 } from "lucide-react";
import Image from "next/image";
import { motion, AnimatePresence } from "framer-motion";

export default function Home() {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    service: "Trabajos en mi Local o Empresa",
    message: ""
  });

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (formData.name.trim().length < 3) newErrors.name = "Ingrese su nombre completo";

    // Validación de teléfono chileno básica
    const phoneRegex = /^(\+?56)?\s?9\s?\d{4}\s?\d{4}$/;
    if (!formData.phone.trim()) {
      newErrors.phone = "El teléfono es requerido";
    } else if (!formData.phone.replace(/\s/g, '').match(/^(\+?56)?9\d{8}$/)) {
      newErrors.phone = "Formato: +56 9 XXXX XXXX";
    }

    if (formData.message.trim().length < 10) newErrors.message = "Por favor, detalle un poco más su requerimiento";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setIsSubmitting(true);

    // Simular envío
    setTimeout(() => {
      setIsSubmitting(false);
      setIsSuccess(true);
      setFormData({ name: "", phone: "", service: "Trabajos en mi Local o Empresa", message: "" });

      // Limpiar después de 5 segundos
      setTimeout(() => setIsSuccess(false), 5000);
    }, 1500);
  };

  return (
    <main className="flex flex-col bg-black overflow-hidden">
      {/* 1. Hero Presentación */}
      <Hero />

      {/* 2. Servicios de Inmediato (Petición del usuario) */}
      <MainServices />

      {/* 3. Quiénes Somos (Autoría Técnica) */}
      <About />

      {/* 4. Barra de Experiencia Rápida */}
      <ExperienceHighlights />

      {/* 5. Galería de Proyectos Reales */}
      <Gallery />

      {/* 7. Formulario de Contacto */}
      <section id="contacto" className="py-40 relative bg-black">
        <div className="container mx-auto px-6">
          <div className="glass p-12 md:p-24 rounded-[4rem] border-white/10 relative overflow-hidden glow-blue">
            <div className="grid lg:grid-cols-2 gap-20 items-center">
              <div>
                <span className="text-blue-400 font-black text-sm tracking-[0.3em] uppercase block mb-8 underline decoration-2 underline-offset-8">Conversémos hoy</span>
                <h2 className="text-5xl md:text-7xl font-black text-white mb-10 leading-[0.9] tracking-tighter">Hagamos realidad <br /> su <span className="text-blue-500 italic">Visión.</span></h2>
                <p className="text-white/50 text-xl mb-12 font-medium">Pida su visita técnica ahora. Vamos a su empresa o domicilio para evaluar su proyecto.</p>

                <div className="space-y-8">
                  <div className="flex items-center gap-6">
                    <div className="w-16 h-16 rounded-3xl bg-blue-600/10 flex items-center justify-center text-blue-500 border border-blue-500/20">
                      <Clock className="w-8 h-8" />
                    </div>
                    <span className="text-white text-lg font-bold italic">Respuesta rápida a su celular</span>
                  </div>
                  <div className="flex items-center gap-6">
                    <div className="w-16 h-16 rounded-3xl bg-blue-600/10 flex items-center justify-center text-blue-500 border border-blue-500/20">
                      <Award className="w-8 h-8" />
                    </div>
                    <span className="text-white text-lg font-bold italic">Presupuestos detallados y honestos</span>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-[3rem] p-10 md:p-16 shadow-2xl skew-x-[-1deg] relative">
                <AnimatePresence>
                  {isSuccess ? (
                    <motion.div
                      initial={{ opacity: 0, scale: 0.8 }}
                      animate={{ opacity: 1, scale: 1 }}
                      className="absolute inset-0 z-10 bg-white rounded-[3rem] flex flex-col items-center justify-center text-center p-10"
                    >
                      <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6">
                        <CheckCircle2 size={40} />
                      </div>
                      <h3 className="text-2xl font-black text-black mb-2 italic">¡Solicitud Enviada!</h3>
                      <p className="text-black/50 font-medium">Lo contactaremos en menos de 24 horas.</p>
                    </motion.div>
                  ) : null}
                </AnimatePresence>

                <form onSubmit={handleSubmit} className="space-y-8">
                  <div className="grid md:grid-cols-2 gap-8">
                    <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <label className="text-black/40 text-xs font-black uppercase tracking-widest ml-2">Su Nombre</label>
                        {errors.name && <span className="text-red-500 text-[10px] font-bold uppercase">{errors.name}</span>}
                      </div>
                      <input
                        type="text"
                        value={formData.name}
                        onChange={(e) => {
                          setFormData({ ...formData, name: e.target.value });
                          if (errors.name) setErrors({ ...errors, name: "" });
                        }}
                        className={`w-full bg-gray-100 border-2 rounded-2xl p-5 text-black font-bold focus:ring-2 ring-blue-500 outline-none transition-all ${errors.name ? 'border-red-500 bg-red-50' : 'border-transparent'}`}
                        placeholder="Juan Pérez"
                      />
                    </div>
                    <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <label className="text-black/40 text-xs font-black uppercase tracking-widest ml-2">Su Teléfono / WhatsApp</label>
                        {errors.phone && <span className="text-red-500 text-[10px] font-bold uppercase">{errors.phone}</span>}
                      </div>
                      <input
                        type="tel"
                        value={formData.phone}
                        onChange={(e) => {
                          setFormData({ ...formData, phone: e.target.value });
                          if (errors.phone) setErrors({ ...errors, phone: "" });
                        }}
                        className={`w-full bg-gray-100 border-2 rounded-2xl p-5 text-black font-bold focus:ring-2 ring-blue-500 outline-none transition-all ${errors.phone ? 'border-red-500 bg-red-50' : 'border-transparent'}`}
                        placeholder="+56 9..."
                      />
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-black/40 text-xs font-black uppercase tracking-widest ml-2">¿Qué necesita realizar?</label>
                    <div className="relative">
                      <select
                        value={formData.service}
                        onChange={(e) => setFormData({ ...formData, service: e.target.value })}
                        className="w-full bg-gray-100 border-none rounded-2xl p-5 text-black font-bold focus:ring-2 ring-blue-500 outline-none appearance-none cursor-pointer px-6"
                      >
                        <option>Trabajos en mi Local o Empresa</option>
                        <option>Reparación o Arreglo Comercial</option>
                        <option>Remodelación o Ampliación en mi Casa</option>
                        <option>Otro requerimiento</option>
                      </select>
                      <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-black/20">
                        ▼
                      </div>
                    </div>
                  </div>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center">
                      <label className="text-black/40 text-xs font-black uppercase tracking-widest ml-2">Cuéntenos un poco más</label>
                      {errors.message && <span className="text-red-500 text-[10px] font-bold uppercase">{errors.message}</span>}
                    </div>
                    <textarea
                      value={formData.message}
                      onChange={(e) => {
                        setFormData({ ...formData, message: e.target.value });
                        if (errors.message) setErrors({ ...errors, message: "" });
                      }}
                      className={`w-full bg-gray-100 border-2 rounded-2xl p-5 text-black font-bold focus:ring-2 ring-blue-500 outline-none h-40 resize-none transition-all ${errors.message ? 'border-red-500 bg-red-50' : 'border-transparent'}`}
                      placeholder="Ej: Necesito pintar mi local y arreglar el piso..."
                    ></textarea>
                  </div>
                  <button
                    disabled={isSubmitting}
                    type="submit"
                    className={`w-full py-6 text-white font-black text-xl rounded-2xl transition-all shadow-xl uppercase tracking-tighter flex items-center justify-center gap-3 ${isSubmitting ? 'bg-gray-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-black shadow-blue-600/20'
                      }`}
                  >
                    {isSubmitting ? 'Enviando...' : 'Pedir Visita o Presupuesto'}
                  </button>
                </form>
              </div>
            </div>
          </div>
        </div>
      </section>
    </main>
  );
}

"use client";

import { motion, AnimatePresence } from 'framer-motion';
import { Target, Users, Shield, Award, CheckCircle2 } from 'lucide-react';
import Image from 'next/image';
import { useState, useEffect } from 'react';

const About = () => {
    const [activeMedia, setActiveMedia] = useState(0);
    const mediaItems = [
        { type: 'video', src: '/img/VID-20260125-WA0141.mp4' },
        { type: 'image', src: '/img/IMG-20260210-WA0141.jpg' },
        { type: 'video', src: '/img/VID-20260125-WA0142.mp4' },
        { type: 'image', src: '/img/IMG-20260210-WA0148.jpg' },
        { type: 'video', src: '/img/VID-20260125-WA0146.mp4' },
        { type: 'image', src: '/img/IMG-20260210-WA0166.jpg' },
        { type: 'image', src: '/img/IMG-20260210-WA0138.jpg' },
        { type: 'video', src: '/img/VID-20260125-WA0021.mp4' }
    ];

    useEffect(() => {
        const timer = setInterval(() => {
            setActiveMedia((prev) => (prev + 1) % mediaItems.length);
        }, 8000);
        return () => clearInterval(timer);
    }, []);

    const categories = [
        { title: "Industrial", desc: "Mantenimiento, estructuras y electricidad semi-industrial.", icon: <Shield className="w-5 h-5" /> },
        { title: "Comercial", desc: "Habilitación de locales, oficinas y centros de distribución.", icon: <Target className="w-5 h-5" /> },
        { title: "Residencial", desc: "Remodelaciones de lujo, ampliaciones y terminaciones de autor.", icon: <Users className="w-5 h-5" /> }
    ];

    return (
        <section id="nosotros" className="py-40 bg-black relative overflow-hidden">
            {/* Background Decorative */}
            <div className="absolute top-1/2 left-0 -translate-y-1/2 w-[800px] h-[800px] bg-blue-600/5 rounded-full blur-[150px] pointer-events-none"></div>

            <div className="container mx-auto px-6 relative z-10">
                <div className="grid lg:grid-cols-2 gap-32 items-start">

                    {/* Visual Side - Dynamic Media Slider */}
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95 }}
                        whileInView={{ opacity: 1, scale: 1 }}
                        viewport={{ once: true }}
                        className="relative group lg:sticky lg:top-32"
                    >
                        <div className="absolute -inset-4 bg-blue-600/10 rounded-[4rem] blur-2xl"></div>

                        <div className="relative aspect-[4/5] rounded-[3.5rem] overflow-hidden border border-white/10 shadow-2xl bg-zinc-900">
                            <AnimatePresence mode="wait">
                                <motion.div
                                    key={activeMedia}
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    exit={{ opacity: 0 }}
                                    transition={{ duration: 1 }}
                                    className="absolute inset-0"
                                >
                                    {mediaItems[activeMedia].type === 'video' ? (
                                        <video
                                            src={mediaItems[activeMedia].src}
                                            autoPlay
                                            muted
                                            loop
                                            playsInline
                                            className="w-full h-full object-cover"
                                        />
                                    ) : (
                                        <Image
                                            src={mediaItems[activeMedia].src}
                                            alt="IMC SERVICIOS SPA"
                                            fill
                                            className="object-cover"
                                        />
                                    )}
                                </motion.div>
                            </AnimatePresence>

                            <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent opacity-80"></div>

                            {/* Slider Dots */}
                            <div className="absolute top-8 right-8 flex gap-2 z-10">
                                {mediaItems.map((_, i) => (
                                    <div
                                        key={i}
                                        className={`h-1.5 rounded-full transition-all duration-500 ${activeMedia === i ? 'w-8 bg-blue-500' : 'w-2 bg-white/20'}`}
                                    />
                                ))}
                            </div>
                        </div>

                        {/* Floating Action Badge */}
                        <motion.div
                            initial={{ opacity: 0, x: 30, y: 30 }}
                            whileInView={{ opacity: 1, x: 0, y: 0 }}
                            transition={{ delay: 0.5 }}
                            viewport={{ once: true }}
                            className="absolute -bottom-10 -right-10 w-48 h-48 rounded-[2rem] glass border border-white/10 flex flex-col items-center justify-center p-6 text-center shadow-2xl hidden md:flex"
                        >
                            <span className="text-4xl font-black text-blue-500">+100</span>
                            <span className="text-[10px] font-black uppercase tracking-widest text-white/60">Proyectos <br /> Entregados</span>
                        </motion.div>
                    </motion.div>

                    {/* Text Content Side */}
                    <div className="pt-10">
                        <motion.div
                            initial={{ opacity: 0, x: -20 }}
                            whileInView={{ opacity: 1, x: 0 }}
                            viewport={{ once: true }}
                            className="inline-flex items-center gap-3 bg-white/5 border border-white/10 rounded-full px-6 py-2 text-blue-400 text-xs font-black tracking-[0.4em] uppercase mb-10"
                        >
                            <Users size={14} /> QUIÉNES SOMOS
                        </motion.div>

                        <h2 className="text-5xl md:text-7xl font-black text-white tracking-tighter leading-[0.9] mb-12">
                            Excelencia en <br /> <span className="text-gradient">360 Grados.</span>
                        </h2>

                        <div className="space-y-8 text-white/50 text-xl font-medium leading-relaxed mb-16 italic">
                            <p>
                                En <span className="text-white font-black not-italic uppercase">IMC SERVICIOS SPA</span>, entendemos que cada proyecto es una inversión crítica. Nuestra capacidad técnica nos permite navegar con maestría entre la <span className="text-white">rigurosidad industrial</span> y la <span className="text-white">estética residencial de lujo</span>.
                            </p>
                            <p>
                                No solo ejecutamos obras; asesoramos desde la ingeniería conceptual hasta el último acabado, asegurando que cada metro cuadrado refleje profesionalismo y durabilidad.
                            </p>
                        </div>

                        {/* Core Pillars Grid */}
                        <div className="grid gap-6 mb-16">
                            {categories.map((cat, i) => (
                                <motion.div
                                    key={i}
                                    initial={{ opacity: 0, y: 10 }}
                                    whileInView={{ opacity: 1, y: 0 }}
                                    transition={{ delay: i * 0.1 }}
                                    viewport={{ once: true }}
                                    className="flex items-center gap-6 p-6 rounded-3xl bg-white/5 border border-white/5 hover:border-blue-500/30 transition-all group"
                                >
                                    <div className="w-14 h-14 rounded-2xl bg-blue-600/10 flex items-center justify-center text-blue-500 group-hover:bg-blue-600 group-hover:text-white transition-all">
                                        {cat.icon}
                                    </div>
                                    <div>
                                        <h4 className="text-white font-black uppercase text-sm tracking-widest mb-1">{cat.title}</h4>
                                        <p className="text-white/40 text-sm font-medium">{cat.desc}</p>
                                    </div>
                                </motion.div>
                            ))}
                        </div>

                        {/* CTAs or Values */}
                        <div className="flex flex-wrap gap-10 items-center">
                            <div className="flex flex-col gap-2">
                                <div className="flex items-center gap-3">
                                    <CheckCircle2 className="text-blue-500 w-6 h-6" />
                                    <span className="text-white/70 font-bold uppercase text-[10px] tracking-widest">Garantía Post-Obra</span>
                                </div>
                                <div className="flex items-center gap-3">
                                    <CheckCircle2 className="text-blue-500 w-6 h-6" />
                                    <span className="text-white/70 font-bold uppercase text-[10px] tracking-widest">Personal Técnico SEC / AWS</span>
                                </div>
                            </div>

                            <div className="h-12 w-px bg-white/10 hidden md:block"></div>

                            <div className="flex gap-6 grayscale opacity-40 hover:grayscale-0 hover:opacity-100 transition-all duration-500">
                                <div className="flex flex-col items-center gap-1">
                                    <Shield className="w-5 h-5 text-white" />
                                    <span className="text-[8px] font-black uppercase tracking-tighter text-white">Seguridad</span>
                                </div>
                                <div className="flex flex-col items-center gap-1">
                                    <Target className="w-5 h-5 text-white" />
                                    <span className="text-[8px] font-black uppercase tracking-tighter text-white">Precisión</span>
                                </div>
                                <div className="flex flex-col items-center gap-1">
                                    <Award className="w-5 h-5 text-white" />
                                    <span className="text-[8px] font-black uppercase tracking-tighter text-white">Calidad</span>
                                </div>
                            </div>
                        </div>
                    </div>

                </div>
            </div>
        </section>
    );
};

export default About;

"use client";

import { motion, useScroll, useTransform } from 'framer-motion';
import {
    ClipboardList,
    CalendarCheck,
    ShieldCheck,
    ArrowRight,
    Zap,
    CheckCircle2
} from 'lucide-react';
import { useRef } from 'react';
import Link from 'next/link';

const steps = [
    {
        num: "01",
        icon: <ClipboardList className="w-10 h-10" />,
        title: "Presupuesto Gratis",
        desc: "Propuesta técnica detallada en menos de 24 horas hábiles.",
        color: "from-blue-600 to-blue-400",
        shadow: "shadow-blue-500/40"
    },
    {
        num: "02",
        icon: <CalendarCheck className="w-10 h-10" />,
        title: "Visita Técnica",
        desc: "Validación experta en terreno para máxima precisión.",
        color: "from-cyan-500 to-blue-500",
        shadow: "shadow-cyan-500/40"
    },
    {
        num: "03",
        icon: <ShieldCheck className="w-10 h-10" />,
        title: "Garantía IMCS",
        desc: "Ejecución profesional con respaldo y post-venta total.",
        color: "from-blue-700 to-indigo-600",
        shadow: "shadow-indigo-500/40"
    }
];

const ExperienceHighlights = () => {
    const containerRef = useRef(null);
    const { scrollYProgress } = useScroll({
        target: containerRef,
        offset: ["start end", "end start"]
    });

    const lineScale = useTransform(scrollYProgress, [0.2, 0.5], [0, 1]);
    const opacity = useTransform(scrollYProgress, [0, 0.2, 0.8, 1], [0, 1, 1, 0]);

    return (
        <section ref={containerRef} className="py-48 relative overflow-hidden bg-black">
            {/* High-Tech Background Elements */}
            <div className="absolute top-0 left-0 w-full h-full opacity-20 pointer-events-none">
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-blue-600/10 rounded-full blur-[120px]"></div>
                <div className="absolute top-1/4 right-0 w-[400px] h-[400px] bg-indigo-600/5 rounded-full blur-[100px]"></div>
            </div>

            <motion.div style={{ opacity }} className="container mx-auto px-6 relative z-10">
                <div className="text-center mb-32">
                    <motion.div
                        initial={{ opacity: 0, scale: 0.9 }}
                        whileInView={{ opacity: 1, scale: 1 }}
                        className="inline-flex items-center gap-3 bg-white/5 backdrop-blur-md border border-white/10 rounded-full px-8 py-3 text-blue-400 text-[11px] font-black tracking-[0.5em] uppercase mb-10 shadow-2xl"
                    >
                        <Zap size={14} className="fill-blue-400" /> EL MÉTODO IMCS
                    </motion.div>
                    <h2 className="text-5xl md:text-7xl font-black text-white tracking-tighter leading-[0.9] mb-12">
                        Nuestro <br /> <span className="text-gradient italic">Proceso.</span>
                    </h2>
                    <p className="text-white/40 text-xl md:text-2xl font-medium max-w-3xl mx-auto italic leading-relaxed">
                        Hemos simplificado la construcción para brindarte <br className="hidden md:block" /> una experiencia sin fricciones y de alta gama.
                    </p>
                </div>

                <div className="relative max-w-6xl mx-auto">
                    {/* Glowing Connecting Line */}
                    <div className="absolute top-24 left-0 w-full h-1 bg-white/5 hidden lg:block overflow-hidden rounded-full">
                        <motion.div
                            style={{ scaleX: lineScale }}
                            className="h-full bg-gradient-to-r from-blue-600 via-cyan-400 to-indigo-600 origin-left shadow-[0_0_20px_rgba(0,106,255,1)]"
                        ></motion.div>
                    </div>

                    <div className="grid lg:grid-cols-3 gap-20 lg:gap-16 relative">
                        {steps.map((step, idx) => (
                            <motion.div
                                key={idx}
                                initial={{ opacity: 0, y: 40 }}
                                whileInView={{ opacity: 1, y: 0 }}
                                viewport={{ once: true }}
                                transition={{ delay: idx * 0.2, duration: 0.8 }}
                                className="relative group"
                            >
                                {/* Visual Node */}
                                <div className="absolute top-24 left-1/2 -translate-x-1/2 -translate-y-1/2 w-6 h-6 rounded-full bg-black border-[3px] border-blue-600 hidden lg:block z-20 group-hover:scale-125 transition-transform shadow-[0_0_15px_rgba(0,106,255,0.5)]">
                                    <div className="w-full h-full bg-blue-600 rounded-full scale-0 group-hover:scale-50 transition-transform"></div>
                                </div>

                                <div className="flex flex-col items-center">
                                    {/* Icon Node Container */}
                                    <div className="mb-14 relative pt-12">
                                        <div className={`w-36 h-36 rounded-[3rem] bg-gradient-to-br ${step.color} p-[1px] ${step.shadow} group-hover:rotate-3 transition-all duration-500`}>
                                            <div className="w-full h-full bg-[#0a0a0b] rounded-[3rem] flex items-center justify-center relative overflow-hidden backdrop-blur-md">
                                                {/* Subtle Number */}
                                                <span className="absolute top-2 right-4 text-5xl font-black text-white/[0.03] select-none italic">
                                                    {step.num}
                                                </span>
                                                <div className="text-white relative z-10 transition-all duration-500 group-hover:scale-110 group-hover:drop-shadow-[0_0_15px_rgba(255,255,255,0.3)]">
